  "publicTaskContract": {
    "publicContract": {
      "goal": "Remove the requested maintenance capacity in accepted batches while keeping every dependent subsystem at or above its declared minimum.",
      "inputGrammar": {
        "notation": "TypeScript",
        "definition": "type RemovalView = { requestId:string, targetCell:string, removeCount:number, maxBatch:number, subsystems:{id:string,current:number,minimum:number,cells:string[]}[] }",
        "validExamples": [
          "{\"requestId\":\"r1\",\"targetCell\":\"c1\",\"removeCount\":2,\"maxBatch\":1,\"subsystems\":[{\"id\":\"index\",\"current\":5,\"minimum\":3,\"cells\":[\"c1\"]}]}"
        ],
        "invalidExamples": [
          "{\"requestId\":\"r1\",\"targetCell\":\"c1\",\"removeCount\":-2,\"subsystems\":[]}"
        ]
      },
      "outputGrammar": {
        "notation": "TypeScript",
        "definition": "type RemovalReport = { status:'COMPLETED'|'REFUSED'|'PARTIAL', acceptedBatches:number[][], removed:number }",
        "validExamples": [
          "{\"status\":\"COMPLETED\",\"acceptedBatches\":[[0],[1]],\"removed\":2}",
          "{\"status\":\"REFUSED\",\"acceptedBatches\":[],\"removed\":0}"
        ],
        "invalidExamples": [
          "{\"status\":\"DONE\",\"removed\":\"all\"}"
        ]
      },
      "stateSemantics": {
        "initialState": "REMOVAL_PLANNED",
        "states": [
          "REMOVAL_PLANNED",
          "BATCH_APPLIED",
          "REMOVAL_COMPLETE",
          "REMOVAL_REFUSED"
        ],
        "transitions": [
          {
            "id": "apply-safe-removal-batch",
            "from": "REMOVAL_PLANNED",
            "input": "Call capacity.remove with at most maxBatch target-cell server indexes.",
            "to": "BATCH_APPLIED",
            "effect": "The harness applies the batch only when every affected subsystem remains at or above minimum."
          },
          {
            "id": "finish-or-refuse-removal",
            "from": "BATCH_APPLIED",
            "input": "Continue with accepted current capacity or stop when the next requested removal would cross a floor.",
            "to": "REMOVAL_COMPLETE",
            "effect": "Report exactly the host-accepted batches and total removals; use PARTIAL when only a prefix is safe."
          }
        ]
      },
      "acceptedOutcomes": [
        "Every batch is no larger than maxBatch, no subsystem falls below minimum, and the report exactly matches accepted host removals."
      ],
      "forbiddenOutcomes": [
        "Crossing any minimum, removing outside targetCell, claiming rejected work, or refusing a wholly safe positive request."
      ],
      "safetyObligations": [
        "Never issue a removal batch that would leave an affected subsystem below its public minimum capacity."
      ],
      "livenessObligations": [
        "Apply at least one batch when the first requested unit is safe and stop only at completion or the first unsafe unit."
      ],
      "implementationFreedom": [
        "The planner may choose any server order and internal data structure when each accepted batch and report obeys the contract."
      ],
      "nonrequirements": [
        "Restart timing, customer traffic, placement algorithms, billing logic, and cross-region recovery are outside this task."
      ]
    },
    "grading": {
      "rules": [
        {
          "id": "capacity-floor-never-crossed",
          "agentVisibleText": "Every accepted batch must leave each affected subsystem current capacity at or above minimum.",
          "publicSection": "Safety floor"
        },
        {
          "id": "capacity-public-batch-limit",
          "agentVisibleText": "No capacity.remove call may contain more than maxBatch server indexes.",
          "publicSection": "Bounded removal"
        },
        {
          "id": "capacity-positive-safe-progress",
          "agentVisibleText": "When one requested removal is safe, at least one accepted removal must occur.",
          "publicSection": "Liveness"
        }
      ],
